import Model from 'flarum/common/Model';

/**
 * Mirrors Ernestdefoe\Hashtags\Api\Resource\HashtagResource.
 *
 * `name` is the display casing (as first written by whoever used it first);
 * `nameKey` is the case-folded form the routes and filters match on. Anything
 * user-facing shows `name`, anything addressable uses `nameKey`.
 */
export default class Hashtag extends Model {
  name() {
    return Model.attribute('name').call(this);
  }
  nameKey() {
    return Model.attribute('nameKey').call(this);
  }
  postCount() {
    return Model.attribute('postCount').call(this);
  }
  discussionCount() {
    return Model.attribute('discussionCount').call(this);
  }
  lastUsedAt() {
    return Model.attribute('lastUsedAt', Model.transformDate).call(this);
  }
}
flarum.reg.add('framio-content', 'hashtags/forum/models/Hashtag', Hashtag);