import app from 'flarum/forum/app';
import { adjustDraftCount, setDraftCount } from '../utils/draftCount';
import ScheduleDraftModal from '../components/ScheduleDraftModal';
export default class DraftsListState {
  loading = false;
  cache = [];
  deleteDraft(draft) {
    if (!window.confirm(app.translator.trans('fof-drafts.forum.dropdown.alert'))) return;
    this.loading = true;
    draft.delete().then(() => {
      adjustDraftCount(-1);
      if (app.composer.body && app.composer.draft && app.composer.draft.id() === draft.id() && !app.composer.changed?.()) {
        app.composer.hide();
      }
      this.loading = false;
      m.redraw();
    });
  }
  scheduleDraft(draft) {
    const canSchedule = Boolean(app.forum.attribute('canScheduleDrafts') || app.forum.attribute('canSaveDrafts') || app.session?.user);
    if (!canSchedule) return;
    app.modal.show(ScheduleDraftModal, {
      draft
    });
  }
  showComposer(draft) {
    if (this.loading) return;
    return new Promise(async resolve => {
      let componentClass;
      switch (draft.type()) {
        case 'privateDiscussion':
          // Use lazy loading for byobu extension
          try {
            const byobuModule = await flarum.reg.asyncModuleImport('ext:fof/byobu/forum/pages/discussions/PrivateDiscussionComposer');
            componentClass = byobuModule.default;
          } catch (e) {
            console.error('Failed to load byobu composer:', e);
            return;
          }
          break;
        case 'reply':
          // Lazy load ReplyComposer
          const replyModule = await flarum.reg.asyncModuleImport('flarum/forum/components/ReplyComposer');
          componentClass = replyModule.default;
          break;
        default:
          // Lazy load DiscussionComposer
          const discussionModule = await flarum.reg.asyncModuleImport('flarum/forum/components/DiscussionComposer');
          componentClass = discussionModule.default;
      }
      const data = draft.compileData();

      // Load composer asynchronously
      await app.composer.load(componentClass, data);
      app.composer.show();
      Object.assign(app.composer.fields, data.fields);
      return resolve(app.composer);
    });
  }
  load(force) {
    if (force === void 0) {
      force = false;
    }
    if (app.cache.draftsLoaded && !force) {
      return;
    }
    this.loading = true;
    m.redraw();
    app.store.find('drafts').then(() => {
      app.cache.draftsLoaded = true;
      setDraftCount(app.store.all('drafts').length);
    }, () => {}).then(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('framio-content', 'drafts/forum/states/DraftsListState', DraftsListState);