import app from 'flarum/forum/app';
import haptic from 'flarum/common/utils/haptic';
import Component from 'flarum/common/Component';
import HeaderList from 'flarum/forum/components/HeaderList';
import Button from 'flarum/common/components/Button';
import Tooltip from 'flarum/common/components/Tooltip';
import ItemList from 'flarum/common/utils/ItemList';
import { setDraftCount } from '../utils/draftCount';
import DraftsListItem from './DraftsListItem';
export default class DraftsList extends Component {
  oncreate(vnode) {
    super.oncreate(vnode);
    $('.draft--delete').on('click tap', function (event) {
      event.stopPropagation();
    });
  }
  deleteAll(e) {
    $(e.currentTarget).trigger('mouseleave');
    if (!confirm(app.translator.trans('fof-drafts.forum.dropdown.delete_all_alert'))) return;
    haptic('heavy');
    app.request({
      method: 'DELETE',
      url: app.forum.attribute('apiUrl') + '/drafts/all'
    }).then(() => {
      // Clear drafts from store
      const drafts = app.store.all('drafts');
      drafts.forEach(draft => app.store.remove(draft));
      setDraftCount(0);
      m.redraw();
    });
  }
  activeFilter = 'all';
  controlItems() {
    const items = new ItemList();
    items.add('deleteAll', m(Tooltip, {
      showOnFocus: false,
      text: app.translator.trans('fof-drafts.forum.dropdown.delete_all_button')
    }, m(Button, {
      "data-container": "body",
      icon: "fas fa-trash-can",
      className: "Button Button--link Button--icon Alert-dismiss",
      onclick: e => {
        this.deleteAll(e);
      }
    })));
    return items;
  }
  view() {
    const allDrafts = app.store.all('drafts');
    const state = this.attrs.state;
    const scheduledCount = allDrafts.filter(d => Boolean(d.scheduledFor())).length;
    const unscheduledCount = allDrafts.filter(d => !d.scheduledFor()).length;
    const drafts = allDrafts.filter(draft => {
      if (this.activeFilter === 'scheduled') {
        return Boolean(draft.scheduledFor());
      }
      if (this.activeFilter === 'drafts') {
        return !draft.scheduledFor();
      }
      return true;
    });
    let emptyText = app.translator.trans('fof-drafts.forum.dropdown.empty_text');
    if (this.activeFilter === 'scheduled') {
      emptyText = 'Zamanlanmış herhangi bir içerik bulunmuyor.';
    } else if (this.activeFilter === 'drafts') {
      emptyText = 'Kayıtlı taslak içerik bulunmuyor.';
    }
    return m(HeaderList, {
      className: "DraftsList",
      title: "Taslak ve Planlamalar",
      controls: this.controlItems(),
      hasItems: allDrafts.length > 0,
      loading: state.loading,
      emptyText: emptyText
    }, allDrafts.length > 0 && m("div", {
      className: "DraftsList-filterTabs"
    }, m("button", {
      type: "button",
      className: `DraftsList-tabBtn ${this.activeFilter === 'all' ? 'active' : ''}`,
      onclick: e => {
        e.preventDefault();
        e.stopPropagation();
        this.activeFilter = 'all';
        m.redraw();
      }
    }, "T\xFCm\xFC (", allDrafts.length, ")"), m("button", {
      type: "button",
      className: `DraftsList-tabBtn ${this.activeFilter === 'drafts' ? 'active' : ''}`,
      onclick: e => {
        e.preventDefault();
        e.stopPropagation();
        this.activeFilter = 'drafts';
        m.redraw();
      }
    }, m("i", {
      className: "fas fa-file-pen",
      style: {
        marginRight: '4px'
      }
    }), "Taslaklar (", unscheduledCount, ")"), m("button", {
      type: "button",
      className: `DraftsList-tabBtn ${this.activeFilter === 'scheduled' ? 'active' : ''}`,
      onclick: e => {
        e.preventDefault();
        e.stopPropagation();
        this.activeFilter = 'scheduled';
        m.redraw();
      }
    }, m("i", {
      className: "far fa-clock",
      style: {
        marginRight: '4px'
      }
    }), "Zamanlanan (", scheduledCount, ")")), m("ul", {
      className: "HeaderListGroup-content"
    }, drafts.sort((a, b) => (b.updatedAt()?.getTime?.() ?? 0) - (a.updatedAt()?.getTime?.() ?? 0)).map(draftItem => {
      return m(DraftsListItem, {
        key: draftItem.id(),
        draft: draftItem,
        state: state
      });
    })));
  }
}
flarum.reg.add('framio-content', 'drafts/forum/components/DraftsList', DraftsList);